import type { Attempt, Job, JobStatus } from './data'

// A tiny job runner, so the table has something live to show. Every function
// takes the jobs and returns new ones; nothing is mutated. In a real app the
// server does this and the table only renders what it reports.

/** How many jobs run at once */
export const CONCURRENCY = 2

/** Wait before automatic retry N: 2s, 4s, 8s… */
export const backoff = (attempt: number) => 2_000 * 2 ** (attempt - 1)

export const isActive = (status: JobStatus) =>
  status === 'queued' || status === 'running' || status === 'retrying'

function endAttempt(job: Job, patch: Partial<Attempt>, now: number): Attempt[] {
  return job.attempts.map((a, i) =>
    i === job.attempts.length - 1
      ? { ...a, endedAt: now, processed: Math.round(job.done), ...patch }
      : a,
  )
}

/** Advances every job to clock time `now`, `dt` ms after the last tick */
export function tick(jobs: Job[], now: number, dt: number): Job[] {
  let next = jobs.map((job): Job => {
    if (
      job.status === 'retrying' &&
      job.retryAt !== undefined &&
      now >= job.retryAt
    ) {
      return { ...job, status: 'queued', retryAt: undefined }
    }
    if (job.status !== 'running') return job

    const done = Math.min(job.total, job.done + (job.rate * dt) / 1000)
    const attempt = job.attempts.length
    const failure = job.failures[attempt - 1] as
      (typeof job.failures)[number] | undefined

    if (failure && done >= failure.at * job.total) {
      const { at: _at, ...error } = failure
      const failed = { ...job, done }
      const attempts = endAttempt(failed, { error }, now)
      // Retry on its own until the attempts run out
      return attempt < job.maxAttempts
        ? {
            ...failed,
            attempts,
            status: 'retrying',
            retryAt: now + backoff(attempt),
          }
        : { ...failed, attempts, status: 'failed' }
    }
    if (done >= job.total) {
      const finished = { ...job, done }
      return {
        ...finished,
        attempts: endAttempt(finished, {}, now),
        status: 'succeeded',
      }
    }
    return { ...job, done }
  })

  // Fill free slots with the jobs that have waited longest
  let running = next.filter((j) => j.status === 'running').length
  const waiting = next
    .filter((j) => j.status === 'queued')
    .sort((a, b) => a.queuedAt - b.queuedAt)
  for (const job of waiting) {
    if (running >= CONCURRENCY) break
    running++
    next = next.map((j) =>
      j.id === job.id
        ? {
            ...j,
            status: 'running',
            done: 0,
            attempts: [
              ...j.attempts,
              { number: j.attempts.length + 1, startedAt: now },
            ],
          }
        : j,
    )
  }
  return next
}

/** Puts a failed or canceled job back in the queue, with one more attempt */
export function retry(jobs: Job[], ids: string[], now: number): Job[] {
  return jobs.map((job) =>
    ids.includes(job.id) &&
    (job.status === 'failed' || job.status === 'canceled')
      ? {
          ...job,
          status: 'queued',
          done: 0,
          queuedAt: now,
          maxAttempts: Math.max(job.maxAttempts, job.attempts.length + 1),
        }
      : job,
  )
}

/** Stops a job that is waiting or running */
export function cancel(jobs: Job[], id: string, now: number): Job[] {
  return jobs.map((job) => {
    if (job.id !== id || !isActive(job.status)) return job
    return {
      ...job,
      status: 'canceled',
      retryAt: undefined,
      attempts:
        job.status === 'running'
          ? endAttempt(job, { canceled: true }, now)
          : job.attempts,
    }
  })
}

/**
 * Time spent running, summed over every attempt: the waits between attempts
 * (backoff, sitting in Failed) don't count. Null until the first attempt.
 */
export function duration(job: Job, now: number) {
  if (!job.attempts.length) return null
  return job.attempts.reduce(
    (sum, a) => sum + ((a.endedAt ?? now) - a.startedAt),
    0,
  )
}

export const formatDuration = (ms: number) => {
  const s = Math.max(0, Math.floor(ms / 1000))
  if (s < 60) return `${s}s`
  const m = Math.floor(s / 60)
  return `${m}m ${String(s % 60).padStart(2, '0')}s`
}

export const hasErrors = (job: Job) => job.attempts.some((a) => a.error)

export type View = 'all' | 'active' | 'failed' | 'done'

export const inView = (status: JobStatus, view: View) =>
  view === 'all' ||
  (view === 'active'
    ? isActive(status)
    : view === 'failed'
      ? status === 'failed'
      : status === 'succeeded' || status === 'canceled')

import {
  Ban,
  CircleAlert,
  CircleCheck,
  Clock,
  LoaderCircle,
  RotateCcw,
  RotateCw,
  X,
  ChevronRight,
} from 'lucide-react'
import type { ColumnDef, Table } from '@tanstack/react-table'

import { Badge } from '#/components/ui/badge'
import { Button } from '#/components/ui/button'
import { cn } from '#/lib/utils'
import type { Job, JobStatus } from './data'
import { duration, formatDuration, inView, isActive } from './queue'
import type { View } from './queue'

export interface QueueMeta {
  /** The demo clock, in ms */
  now: number
  retry: (id: string) => void
  cancel: (id: string) => void
}

const getMeta = (table: Table<Job>) =>
  table.options.meta as unknown as QueueMeta

const statusStyle: Record<
  JobStatus,
  { label: string; icon: typeof Clock; badge: string; bar: string }
> = {
  queued: {
    label: 'Queued',
    icon: Clock,
    badge: 'text-muted-foreground',
    bar: 'bg-muted-foreground/40',
  },
  running: {
    label: 'Running',
    icon: LoaderCircle,
    badge: 'border-blue-500/40 text-blue-700 dark:text-blue-400',
    bar: 'bg-blue-500',
  },
  retrying: {
    label: 'Retrying',
    icon: RotateCw,
    badge: 'border-amber-500/50 text-amber-800 dark:text-amber-300',
    bar: 'bg-amber-500',
  },
  succeeded: {
    label: 'Succeeded',
    icon: CircleCheck,
    badge: 'border-emerald-500/40 text-emerald-700 dark:text-emerald-400',
    bar: 'bg-emerald-500',
  },
  failed: {
    label: 'Failed',
    icon: CircleAlert,
    badge: 'border-destructive/40 text-destructive',
    bar: 'bg-destructive',
  },
  canceled: {
    label: 'Canceled',
    icon: Ban,
    badge: 'text-muted-foreground',
    bar: 'bg-muted-foreground/40',
  },
}

export const columns: ColumnDef<Job>[] = [
  {
    id: 'expand',
    header: () => <span className="sr-only">Errors</span>,
    cell: ({ row }) =>
      row.getCanExpand() ? (
        <Button
          variant="ghost"
          size="icon"
          className="size-7"
          onClick={row.getToggleExpandedHandler()}
          aria-expanded={row.getIsExpanded()}
          aria-label={`${row.getIsExpanded() ? 'Hide' : 'Show'} errors for ${row.original.name}`}
        >
          <ChevronRight
            className={cn(
              'transition-transform motion-reduce:transition-none',
              row.getIsExpanded() && 'rotate-90',
            )}
          />
        </Button>
      ) : null,
  },
  {
    id: 'job',
    header: 'Job',
    accessorFn: (job) => job.name,
    cell: ({ row }) => (
      <div className="flex min-w-40 flex-col gap-0.5">
        <span className="font-medium">{row.original.name}</span>
        <span className="font-mono text-xs text-muted-foreground">
          {row.original.queue} · {row.original.id}
        </span>
      </div>
    ),
  },
  {
    id: 'status',
    header: 'Status',
    accessorFn: (job) => job.status,
    filterFn: (row, _id, view: View) => inView(row.original.status, view),
    cell: ({ row, table }) => {
      const { status, retryAt } = row.original
      const style = statusStyle[status]
      const Icon = style.icon
      const wait =
        status === 'retrying' && retryAt !== undefined
          ? formatDuration(retryAt - getMeta(table).now + 999)
          : null
      return (
        <Badge variant="outline" className={cn('gap-1', style.badge)}>
          <Icon
            className={cn(
              'size-3',
              status === 'running' && 'motion-safe:animate-spin',
            )}
          />
          {style.label}
          {wait ? <span className="tabular-nums">in {wait}</span> : null}
        </Badge>
      )
    },
  },
  {
    id: 'progress',
    header: 'Progress',
    cell: ({ row }) => {
      const { status, done, total, name } = row.original
      const pct = Math.floor((done / total) * 100)
      return (
        <div className="flex min-w-40 flex-col gap-1">
          <div
            role="progressbar"
            aria-label={`${name} progress`}
            aria-valuemin={0}
            aria-valuemax={100}
            aria-valuenow={pct}
            className="h-1.5 overflow-hidden rounded-full bg-muted"
          >
            <div
              className={cn(
                'h-full rounded-full transition-[width] duration-200 ease-linear motion-reduce:transition-none',
                statusStyle[status].bar,
              )}
              style={{ width: `${pct}%` }}
            />
          </div>
          <span className="text-xs text-muted-foreground tabular-nums">
            {status === 'queued'
              ? `Waiting · ${total.toLocaleString('en-US')} items`
              : `${pct}% · ${Math.round(done).toLocaleString('en-US')} / ${total.toLocaleString('en-US')}`}
          </span>
        </div>
      )
    },
  },
  {
    id: 'attempts',
    header: () => <span className="block text-right">Attempts</span>,
    cell: ({ row }) => {
      const { attempts, maxAttempts } = row.original
      const failed = attempts.filter((a) => a.error).length
      return (
        <span
          className="block text-right tabular-nums"
          title={failed ? `${failed} failed` : undefined}
        >
          {attempts.length}
          <span className="text-muted-foreground"> / {maxAttempts}</span>
        </span>
      )
    },
  },
  {
    id: 'duration',
    header: () => <span className="block text-right">Duration</span>,
    cell: ({ row, table }) => {
      const ms = duration(row.original, getMeta(table).now)
      return (
        <span className="block text-right text-muted-foreground tabular-nums">
          {ms === null ? '—' : formatDuration(ms)}
        </span>
      )
    },
  },
  {
    id: 'actions',
    header: () => <span className="sr-only">Actions</span>,
    cell: ({ row, table }) => {
      const { retry, cancel } = getMeta(table)
      const { id, name, status } = row.original
      if (status === 'failed' || status === 'canceled') {
        return (
          <div className="flex justify-end">
            <Button
              variant="outline"
              size="sm"
              aria-label={`Retry ${name}`}
              onClick={() => retry(id)}
            >
              <RotateCcw /> Retry
            </Button>
          </div>
        )
      }
      if (isActive(status)) {
        return (
          <div className="flex justify-end">
            <Button
              variant="ghost"
              size="sm"
              aria-label={`Cancel ${name}`}
              onClick={() => cancel(id)}
            >
              <X /> Cancel
            </Button>
          </div>
        )
      }
      return null
    },
  },
]

import { CircleAlert, CircleCheck, LoaderCircle } from 'lucide-react'

import type { Job } from './data'
import { formatDuration, isActive } from './queue'

/**
 * The expanded row: every attempt, newest first. Failed attempts show their
 * error code, message and stack trace, so a retry can be judged on what
 * actually went wrong.
 */
export function JobErrors({ job }: { job: Job }) {
  const attempts = [...job.attempts].reverse()
  return (
    <ol className="space-y-3">
      {attempts.map((attempt) => {
        const running = !attempt.endedAt && isActive(job.status)
        const took =
          attempt.endedAt !== undefined
            ? formatDuration(attempt.endedAt - attempt.startedAt)
            : null
        return (
          <li key={attempt.number} className="space-y-1.5">
            <p className="flex flex-wrap items-center gap-x-2 gap-y-1 text-sm">
              {attempt.error ? (
                <CircleAlert className="size-4 text-destructive" />
              ) : running ? (
                <LoaderCircle className="size-4 text-blue-600 motion-safe:animate-spin" />
              ) : (
                <CircleCheck className="size-4 text-muted-foreground" />
              )}
              <span className="font-medium">Attempt {attempt.number}</span>
              <span className="text-muted-foreground">
                {running
                  ? 'running now'
                  : attempt.error
                    ? `failed after ${took} at ${attempt.processed?.toLocaleString('en-US')} of ${job.total.toLocaleString('en-US')} items`
                    : attempt.canceled
                      ? `canceled after ${took}`
                      : `succeeded in ${took}`}
              </span>
            </p>
            {attempt.error ? (
              <div className="ml-6 overflow-hidden rounded-md border border-destructive/20">
                <p className="flex flex-wrap gap-x-2 bg-destructive/5 px-3 py-2 text-sm">
                  <code className="font-mono text-xs font-medium text-destructive">
                    {attempt.error.code}
                  </code>
                  <span>{attempt.error.message}</span>
                </p>
                <pre className="overflow-x-auto px-3 py-2 font-mono text-xs leading-relaxed text-muted-foreground">
                  {attempt.error.trace
                    .map((line, i) => (i === 0 ? line : `    ${line}`))
                    .join('\n')}
                </pre>
              </div>
            ) : null}
          </li>
        )
      })}
    </ol>
  )
}

import { Fragment, useMemo, useState } from 'react'
import {
  flexRender,
  getCoreRowModel,
  getExpandedRowModel,
  getFilteredRowModel,
  useReactTable,
} from '@tanstack/react-table'
import type { ExpandedState } from '@tanstack/react-table'

import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '#/components/ui/table'
import { cn } from '#/lib/utils'
import { columns } from './columns'
import type { QueueMeta } from './columns'
import type { Job } from './data'
import { JobErrors } from './job-errors'
import { hasErrors } from './queue'
import type { View } from './queue'

export function JobQueueTable({
  jobs,
  view,
  meta,
}: {
  jobs: Job[]
  view: View
  meta: QueueMeta
}) {
  const [expanded, setExpanded] = useState<ExpandedState>({})
  // Memoized: a new filter array on every tick would refilter for nothing
  const columnFilters = useMemo(
    () => (view === 'all' ? [] : [{ id: 'status', value: view }]),
    [view],
  )

  const table = useReactTable({
    data: jobs,
    columns,
    // Ids keep a row (and whether it's expanded) stable while jobs update
    getRowId: (job) => job.id,
    getRowCanExpand: (row) => hasErrors(row.original),
    getCoreRowModel: getCoreRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    getExpandedRowModel: getExpandedRowModel(),
    state: { expanded, columnFilters },
    onExpandedChange: setExpanded,
    // The data changes several times a second; nothing should reset with it
    autoResetExpanded: false,
    autoResetPageIndex: false,
    meta,
  })

  const rows = table.getRowModel().rows

  return (
    <div className="overflow-hidden rounded-md border">
      <Table>
        <TableHeader>
          {table.getHeaderGroups().map((headerGroup) => (
            <TableRow key={headerGroup.id} className="hover:bg-transparent">
              {headerGroup.headers.map((header) => (
                <TableHead
                  key={header.id}
                  className={cn(header.column.id === 'expand' && 'w-10')}
                >
                  {flexRender(
                    header.column.columnDef.header,
                    header.getContext(),
                  )}
                </TableHead>
              ))}
            </TableRow>
          ))}
        </TableHeader>
        <TableBody>
          {rows.length ? (
            rows.map((row) => (
              <Fragment key={row.id}>
                <TableRow
                  className={cn(
                    row.original.status === 'failed' &&
                      'bg-destructive/[0.03] hover:bg-destructive/[0.06]',
                    row.getIsExpanded() && 'border-b-0',
                  )}
                >
                  {row.getVisibleCells().map((cell) => (
                    <TableCell key={cell.id} className="py-2.5">
                      {flexRender(
                        cell.column.columnDef.cell,
                        cell.getContext(),
                      )}
                    </TableCell>
                  ))}
                </TableRow>
                {row.getIsExpanded() ? (
                  <TableRow className="hover:bg-transparent">
                    <TableCell
                      colSpan={columns.length}
                      className="bg-muted/30 py-4 pr-4 pl-12 whitespace-normal"
                    >
                      <JobErrors job={row.original} />
                    </TableCell>
                  </TableRow>
                ) : null}
              </Fragment>
            ))
          ) : (
            <TableRow className="hover:bg-transparent">
              <TableCell
                colSpan={columns.length}
                className="h-24 text-center text-muted-foreground"
              >
                {view === 'failed' ? 'No failed jobs.' : `No ${view} jobs.`}
              </TableCell>
            </TableRow>
          )}
        </TableBody>
      </Table>
    </div>
  )
}

import { useEffect, useState } from 'react'
import { RotateCcw } from 'lucide-react'

import { Button } from '#/components/ui/button'
import { seedJobs } from './data'
import type { Job } from './data'
import { JobQueueTable } from './data-table'
import { CONCURRENCY, cancel, inView, isActive, retry, tick } from './queue'
import type { View } from './queue'

const TICK = 200

const views: { id: View; label: string }[] = [
  { id: 'all', label: 'All' },
  { id: 'active', label: 'Active' },
  { id: 'failed', label: 'Failed' },
  { id: 'done', label: 'Done' },
]

interface Queue {
  /** Demo clock in ms. It starts at 0 on the server and in the browser alike,
   *  so both render the same durations. */
  now: number
  jobs: Job[]
}

const start = (): Queue => ({ now: 0, jobs: seedJobs() })

export function JobQueueDemo() {
  const [queue, setQueue] = useState<Queue>(start)
  const [view, setView] = useState<View>('all')
  const { now, jobs } = queue

  const busy = jobs.some((j) => isActive(j.status))
  // The clock only runs while something is queued, running or retrying
  useEffect(() => {
    if (!busy) return
    const timer = setInterval(() => {
      setQueue((q) => ({
        now: q.now + TICK,
        jobs: tick(q.jobs, q.now + TICK, TICK),
      }))
    }, TICK)
    return () => clearInterval(timer)
  }, [busy])

  const count = (v: View) => jobs.filter((j) => inView(j.status, v)).length
  const running = jobs.filter((j) => j.status === 'running').length
  const waiting = jobs.filter(
    (j) => j.status === 'queued' || j.status === 'retrying',
  ).length
  const failed = jobs.filter((j) => j.status === 'failed')

  const update = (fn: (jobs: Job[]) => Job[]) =>
    setQueue((q) => ({ ...q, jobs: fn(q.jobs) }))

  return (
    <div className="space-y-3">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <p className="text-sm text-muted-foreground">
          <span className="font-medium text-foreground">
            {running} of {CONCURRENCY} workers busy
          </span>
          {' · '}
          {waiting} waiting · {failed.length} failed
        </p>
        <div className="flex gap-2">
          <Button
            variant="outline"
            size="sm"
            disabled={!failed.length}
            onClick={() =>
              update((js) =>
                retry(
                  js,
                  failed.map((j) => j.id),
                  now,
                ),
              )
            }
          >
            <RotateCcw /> Retry all failed
          </Button>
          <Button variant="ghost" size="sm" onClick={() => setQueue(start())}>
            Reset demo
          </Button>
        </div>
      </div>

      <div
        role="group"
        aria-label="Show jobs"
        className="inline-flex rounded-md border p-0.5"
      >
        {views.map((v) => (
          <button
            key={v.id}
            type="button"
            aria-pressed={view === v.id}
            onClick={() => setView(v.id)}
            className="flex h-7 items-center gap-1.5 rounded px-2.5 text-sm text-muted-foreground outline-none hover:text-foreground focus-visible:ring-[3px] focus-visible:ring-ring/50 aria-pressed:bg-muted aria-pressed:text-foreground"
          >
            {v.label}
            <span className="text-xs tabular-nums">{count(v.id)}</span>
          </button>
        ))}
      </div>

      <JobQueueTable
        jobs={jobs}
        view={view}
        meta={{
          now,
          retry: (id) => update((js) => retry(js, [id], now)),
          cancel: (id) => update((js) => cancel(js, id, now)),
        }}
      />
    </div>
  )
}
